        this.orders = orders;
        this.lines = lines;
        this.customers = customers;
        this.items = items;
        this.service = service;
    }

    @QueryMapping
    public Order order(@Argument Long id) {
        return orders.findById(id).orElseThrow(() -> new OrderNotFoundException(id));
