// A slice: the schema, the controller and the exception resolver, no database.
@GraphQlTest(StoreController.class)
@Import(StoreExceptionResolver.class)
class StoreControllerTests {

    @Autowired
    GraphQlTester graphQlTester;

    @MockitoBean OrderRepository orders;
    @MockitoBean OrderLineRepository lines;
    @MockitoBean CustomerRepository customers;
    @MockitoBean ItemRepository items;
    @MockitoBean OrderService service;

    @Test
    void returnsTheFieldsAskedFor() {
        given(orders.findById(1L)).willReturn(
                Optional.of(new Order(1L, 3_000, Instant.parse("2026-09-01T10:00:00Z"))));

        graphQlTester.document("{ order(id: 1) { status total } }")
                .execute()
                .path("order.status").entity(String.class).isEqualTo("PLACED")
                .path("order.total").entity(Integer.class).isEqualTo(3000);
    }

    @Test
    void aMissingOrderIsNotFound() {
        given(orders.findById(999L)).willReturn(Optional.empty());

        graphQlTester.document("{ order(id: 999) { id } }")
                .execute()
                .errors()
                .expect(error -> error.getErrorType() == ErrorType.NOT_FOUND);
    }

    @Test
    void orderCountIsTheCustomersNumberOfOrders() {
        given(orders.findById(2L)).willReturn(Optional.of(order(2L, 2L)));
        given(customers.findAllById(List.of(2L))).willReturn(List.of(customer(2L, "Grace")));
        given(orders.countByCustomerIdIn(List.of(2L)))
                .willReturn(List.of(new CustomerOrderCount(2L, 10L)));

        graphQlTester.document("{ order(id: 2) { customer { id orderCount } } }")
                .execute()
                .path("order.customer.id").entity(String.class).isEqualTo("2")
                .path("order.customer.orderCount").entity(Integer.class).isEqualTo(10);
    }

    @Test
    void orderCountIsOneQueryForEveryCustomerInTheResponse() {
        List<Order> page = List.of(order(1L, 1L), order(2L, 2L), order(3L, 1L), order(4L, 3L));
        given(orders.findBy(any(), any(), any())).willReturn(window(page, false));
        given(customers.findAllById(anyCollection())).willReturn(
                List.of(customer(1L, "Ada"), customer(2L, "Grace"), customer(3L, "Linus")));
        // Linus has no row: a customer with no orders is not in a "group by".
        given(orders.countByCustomerIdIn(anyCollection())).willReturn(
                List.of(new CustomerOrderCount(1L, 7L), new CustomerOrderCount(2L, 4L)));

        graphQlTester.document(
                        "{ orders(first: 50) { edges { node { customer { id orderCount } } } } }")
                .execute()
                .path("orders.edges[*].node.customer.orderCount").entityList(Integer.class)
                .isEqualTo(List.of(7, 4, 7, 0));

        @SuppressWarnings("unchecked")
        ArgumentCaptor<Collection<Long>> ids = ArgumentCaptor.forClass(Collection.class);
        verify(orders, times(1)).countByCustomerIdIn(ids.capture());
        assertThat(ids.getValue()).containsExactlyInAnyOrder(1L, 2L, 3L);
    }

    @Test
    void customerOrdersReturnsTheFirstPageOfThatCustomer() {
        given(customers.existsById(2L)).willReturn(true);
